export const PROFILE={sha256:'2d1adf301d051f2cc956855c44c3931b35ddee1e3a0a586f5f324fe5064bbcf5',sizes:[3264,4084,4084,4084,1556,4084,4084,4084,4084,4084,4084,4084,4084,304],money:0x400,key:0x40,maxMoney:9999999};
const dv=b=>new DataView(b.buffer,b.byteOffset,b.byteLength);
export function checksum(b,start,size){let n=0,v=dv(b);for(let i=0;i<Math.floor(size/4)*4;i+=4)n=(n+v.getUint32(start+i,true))>>>0;return ((n>>>16)+(n&65535))&65535;}
export function encodeName(s){if(!/^[A-Za-z0-9 .-]{1,7}$/.test(s)||!s.trim())throw Error('ใช้ชื่อภาษาอังกฤษ ตัวเลข ช่องว่าง จุด หรือขีด 1–7 ตัวอักษร');const out=new Uint8Array(8).fill(255);[...s].forEach((c,i)=>out[i]=c===' '?0:c==='.'?0xad:c==='-'?0xae:/[A-Z]/.test(c)?c.charCodeAt(0)-65+0xbb:/[a-z]/.test(c)?c.charCodeAt(0)-97+0xd5:c.charCodeAt(0)-48+0xa1);return out;}
export function decodeName(b){let s='';for(const c of b){if(c===255)break;s+=c===0?' ':c===0xad?'.':c===0xae?'-':c>=0xbb&&c<=0xd4?String.fromCharCode(c-0xbb+65):c>=0xd5&&c<=0xee?String.fromCharCode(c-0xd5+97):c>=0xa1&&c<=0xaa?String(c-0xa1):'�';}return s;}
export function parseSave(input){const b=new Uint8Array(input);if(b.length!==131072)throw Error('ต้องเป็นเซฟในเกมขนาด 128 KB (.sav หรือ .srm) ไม่รองรับ Save State หรือเซฟที่ขนาดต่างจากนี้');const v=dv(b),slots=[];for(let slot=0;slot<2;slot++){const base=slot*14*4096, region=b.subarray(base,base+14*4096);if(region.every(x=>x===255)||region.every(x=>x===0))continue;const sections=new Map();let counter;for(let j=0;j<14;j++){const p=base+j*4096,id=v.getUint16(p+0xff4,true),n=v.getUint32(p+0xffc,true);if(id>13||sections.has(id)||v.getUint32(p+0xff8,true)!==0x08012025)throw Error('โครงสร้างเซฟไม่ตรงกับ ROM นี้ หรือมีส่วนข้อมูลไม่ครบ — ยังไม่เปิดให้แก้ไข');if(counter!==undefined&&counter!==n)throw Error('พบการบันทึกที่ไม่ครบชุด — ยังไม่เปิดให้แก้ไข');counter=n;if(checksum(b,p,PROFILE.sizes[id])!==v.getUint16(p+0xff6,true))throw Error('Checksum ไม่ตรงกับ ROM นี้ หรือเซฟเสียหาย — ยังไม่เปิดให้แก้ไข');sections.set(id,p);}slots.push({slot,counter,sections});}if(!slots.length)throw Error('ยังไม่มีข้อมูลเกมที่บันทึกไว้ในไฟล์นี้');let active=slots[0];if(slots.length===2){const delta=(slots[1].counter-active.counter)>>>0;if(delta===0||delta===0x80000000)throw Error('ไม่สามารถระบุชุดเซฟล่าสุดได้อย่างแน่นอน');if(delta<0x80000000)active=slots[1];}const trainer=active.sections.get(0),world=active.sections.get(1),nameBytes=b.slice(trainer,trainer+8),name=decodeName(nameBytes),key=v.getUint32(trainer+PROFILE.key,true),money=(v.getUint32(world+PROFILE.money,true)^key)>>>0;if(!nameBytes.includes(255)||nameBytes[0]===255||b[trainer+8]>1||money>PROFILE.maxMoney)throw Error('ข้อมูลผู้เล่นไม่ตรงกับรูปแบบที่รองรับ — ยังไม่เปิดให้แก้ไข');return {bytes:b,active,slots,name,nameBytes,money,key,trainer,world,tid:v.getUint16(trainer+10,true)};}
export function editSave(input,changes){const s=parseSave(input),out=s.bytes.slice(),v=dv(out),modified=new Set();if(changes.name!==undefined&&changes.name!==s.name){out.set(encodeName(changes.name),s.trainer);modified.add(0);}if(changes.money!==undefined&&changes.money!==s.money){if(!Number.isInteger(changes.money)||changes.money<0||changes.money>PROFILE.maxMoney)throw Error('เงินต้องเป็นจำนวนเต็ม 0–9,999,999');v.setUint32(s.world+PROFILE.money,(changes.money^s.key)>>>0,true);modified.add(1);}for(const id of modified){const p=s.active.sections.get(id);v.setUint16(p+0xff6,checksum(out,p,PROFILE.sizes[id]),true);}parseSave(out);return out;}
